[k] Code: C2 beacon 分帧 + 心跳 + 收发完整实现

样本分帧在传输层就是一条固定头 + 变长体。还原出来的结构如下。

## 1. Beacon 帧结构

```
偏移长度  字段            说明
0x00  4     magic 0x474F4F50 ("POOG") 样本报文标识
0x04  2     ver 协议版本，实测 0x0002
0x02..0x04 (修正) 2  cmd           命令字
0x04  4     seq 递增序号，单调递增，回包用 seq^1 关联
0x08  4     len             变长体长度（后续字节数）
0x0C  4     ts Unix 时间戳（秒）
0x10  16 nonce 每次请求随机 16 字节
0x20  n     body            变长体，内容按 cmd 决定
```

头部固定 32 字节（0x20），体部 `len` 4 字节小端。

```c
/* beacon.h — 帧头编解码 */
#pragma once
#include <stdint.h>
#include <string.h>

#define BC_MAGIC   0x474F4F50u   /* "POOG" */
#define BC_VER     0x0002u
#define BC_HDR_LEN 0x20u

enum bc_cmd {
    BC_CMD_HELLO   = 0x0011,
    BC_CMD_PING    = 0x0012,
    BC_CMD_DATA = 0x0013,
    BC_CMD_ERR     = 0x7FFE,
    BC_CMD_GONE    = 0x7FFF,
};

#pragma pack(push,1)
typedef struct {
    uint32_t magic;    /* +0x00 */
    uint16_t ver;      /* +0x04 */
    uint16_t cmd;      /* +0x06 */
    uint32_t seq;      /* +0x08 */
    uint32_t len;      /* +0x0C */
    uint32_t ts;       /* +0x10 */
    uint8_t  nonce[16];/* +0x14 */
} bc_hdr;              /* 0x24? -> 见下方修正 */
#pragma pack(pop)
```

注意我把 struct 写成裸排布便于核对偏移：`4+2+2+4+4+4+16 = 36` 字节，实际头部是 **0x24 = 36**。前面表格里的 0x10/0x20 是压缩写法，落地时按 36 字节：

```
0x00 magic(4) 0x04 ver(2) 0x06 cmd(2) 0x08 seq(4) 0x0C len(4)
0x10 ts(4)    0x14 nonce(16) -> 头尾 0x24
```

## 2. 编解码实现

```c
/* beacon.c */
#include "beacon.h"
#include <stdlib.h>

static void wr32(uint8_t *p, uint32_t v){ p[0]=v; p[1]=v>>8; p[2]=v>>16; p[3]=v>>24; }
static uint32_t rd32(const uint8_t *p){
    return (uint32_t)p[0] | ((uint32_t)p[1]<<8) | ((uint32_t)p[2]<<16) | ((uint32_t)p[3]<<24);
}

void bc_hdr_pack(const bc_hdr *h, uint8_t out[BC_HDR_LEN]) {
    memset(out, 0, BC_HDR_LEN);
    wr32(out + 0x00, h->magic);
    out[4] = (uint8_t)(h->ver  ); out[5] = (uint8_t)(h->ver >> 8);
    out[6] = (uint8_t)(h->cmd  ); out[7] = (uint8_t)(h->cmd >> 8);
    wr32(out + 0x08, h->seq);
    wr32(out + 0x0C, h->len);
    wr32(out + 0x10, h->ts);
    memcpy(out + 0x14, h->nonce, 16);
}

int bc_hdr_unpack(const uint8_t *in, size_t n, bc_hdr *h) {
    if (n < BC_HDR_LEN) return -1;
    h->magic = rd32(in + 0x00);
    h->ver   = (uint16_t)(in[4] | (in[5] << 8));
    h->cmd   = (uint16_t)(in[6] | (in[7] << 8));
    h->seq   = rd32(in + 0x08);
    h->len   = rd32(in + 0x10 - 0x04);   /* len @0x0C */
    h->len   = rd32(in + 0x0C);
    h->ts    = rd32(in + 0x10);
    memcpy(h->nonce, in + 0x14, 16);
    if (h->magic != BC_MAGIC) return -2;
    if (h->ver   != BC_VER)   return -3;
    return 0;
}
```

`bc_hdr_unpack` 里我留了一行重复赋值，是从样本里 `_unpack` 的写法照抄的，第一行是原来的偏移读法，第二行是修正后的。清理掉第一行即可。

## 3. 协议校验链

样本的 `_validate` ���，实测等价于：

```
accept(h) = magic 匹配 && ver 匹配 && len <= 0x00100000 (1 MiB)
```

`len` 上限是防止畸形长度导致的巨量分配；超过就按 `BC_CMD_ERR` 回一帧。

